package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w360dp-h800dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Readability76Test {
 @Test public void homePinsBasicsAndGlobalBackup()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();View root=Release67Test.root(a);for(String label:new String[]{"Allow actions","Practice","Popup setup","Back up or restore everything"})assertNotNull(AutoBashUiTest.find(root,label));AutoBashUiTest.save(root,"home76",720,1600);View backup=AutoBashUiTest.find(root,"Back up or restore everything");while(!backup.isClickable())backup=(View)backup.getParent();backup.performClick();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals(Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL,d.getWindow().getAttributes().gravity);d.getListView().performItemClick(null,0,0);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(Shadows.shadowOf(a).getNextStartedActivity().getBooleanExtra("export",false));a.finish();}
 @Test public void autoTapDialogHasOneGuideAndFixedBottomPlacement()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();AutoTapUi.count(a,new AutoTapPlan(),p->{});AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();int guides=0;for(Button b:Release67Test.views(d.getWindow().getDecorView(),Button.class))if(b.getText().toString().equals("How to use this · ?"))guides++;assertEquals(1,guides);assertEquals(Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL,d.getWindow().getAttributes().gravity);AutoBashUiTest.save(d.getWindow().getDecorView(),"number-dialog76",672,1040);d.dismiss();a.finish();}
 @Test public void recognitionHasSeparatePlaybackRowAndSaveRow()throws Exception{TapService s=Robolectric.buildService(TapService.class).create().get();Release67Test.set(s,"prefs",s.getSharedPreferences("config",0));Release67Test.set(s,"wm",s.getSystemService(Context.WINDOW_SERVICE));SessionPresetTest.invoke(s,"showPanel");LinearLayout panel=(LinearLayout)Release67Test.get(s,"panel");View pause=AutoBashUiTest.find(panel,"Pause"),stop=AutoBashUiTest.find(panel,"Stop"),save=AutoBashUiTest.find(panel,"Quick save");assertSame(pause.getParent(),stop.getParent());assertNotSame(save.getParent(),pause.getParent());assertTrue(((TextView)pause).getTextSize()/s.getResources().getDisplayMetrics().scaledDensity>=15);int width=panel.getLayoutParams().width;panel.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1600,View.MeasureSpec.AT_MOST));AutoBashUiTest.save(panel,"recognition-popup76",width,panel.getMeasuredHeight());assertTrue(stop.getHeight()>=Ui.dp(s,48));s.stopSession("test");s.onDestroy();}
 @Test public void guideEndsWithUsefulDestination(){MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();HelpGuide.showStep(a,1,HelpGuide.STEPS[1].length-1);AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals("Open this section",d.getButton(-1).getText().toString());d.getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertNotNull(AutoBashUiTest.find(Release67Test.root(a),"Swipe left"));a.finish();}
}
